cd data/proving-ground/2026-09-08-bench-h1-product-loop-t5/sessions && node -e '
const fs=require("fs");
for (const f of fs.readdirSync(".")) {
  const lines=fs.readFileSync(f,"utf8").trim().split("\n").map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean);
  const evs=lines.filter(e=>e.type);
  if(evs.length===0) continue;
  const first=evs[0].time, last=evs[evs.length-1].time;
  const dels=evs.filter(e=>e.type==="environment/delegation");
  const cost=dels.reduce((s,e)=>s+(e.data.reportedCostUsd??0),0);
  const env=evs.find(e=>e.type==="environment/run")?.data.environmentId;
  const cert=evs.some(e=>e.type==="verification/certificate");
  console.log([env, ((last-first)/1000).toFixed(0)+"s", dels.length+" att", cost.toFixed(2)+" USD", cert?"certified":"MISS"].join("  "));
}' 2>&1 | sort -t' ' -k3 -rn | head -20

cd data/proving-ground/2026-09-08-bench-h1-product-loop-t5/sessions && node -e '
const fs=require("fs");
const rows=[];
for (const f of fs.readdirSync(".")) {
  const evs=fs.readFileSync(f,"utf8").trim().split("\n").map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(e=>e&&typeof e.time==="number"&&e.type);
  if(evs.length===0) continue;
  const times=evs.map(e=>e.time);
  const dur=(Math.max(...times)-Math.min(...times))/1000;
  const dels=evs.filter(e=>e.type==="environment/delegation");
  const cost=dels.reduce((s,e)=>s+(e.data.reportedCostUsd??0),0);
  const env=evs.find(e=>e.type==="environment/run")?.data.environmentId;
  const cert=evs.some(e=>e.type==="verification/certificate");
  rows.push({env,dur:Math.round(dur),att:dels.length,cost:+cost.toFixed(2),cert});
}
rows.sort((a,b)=>b.dur-a.dur);
for(const r of rows) console.log(`${String(r.dur).padStart(5)}s  ${r.att} att  ${String(r.cost).padStart(5)} USD  ${r.cert?"certified":"MISS     "}  ${r.env}`);
console.log("breach events:", rows.length && fs.readdirSync(".").filter(f=>fs.readFileSync(f,"utf8").includes("budget/breach")).length);
'

